import React, { useRef, useState } from 'react';
import { createPortal } from 'react-dom';

export type LawArticleRefMeta = {
  title: string;
  timeliness: string;
  href?: string;
  /** 是否展示「近似识别」标签（民法典） */
  approximate?: boolean;
};

/** 关联法条 mock 元数据（key：`法律名》后缀`，如 `劳动合同法》第39条`） */
export const LAW_ARTICLE_REF_REGISTRY: Record<string, LawArticleRefMeta> = {
  '劳动合同法》第39条': {
    title: '中华人民共和国劳动合同法',
    timeliness: '现行有效',
    href: '#law-labor-contract-39',
  },
  '劳动合同法》第38条': {
    title: '中华人民共和国劳动合同法',
    timeliness: '现行有效',
    href: '#law-labor-contract-38',
  },
  '未成年人保护法》第62条': {
    title: '中华人民共和国未成年人保护法',
    timeliness: '现行有效',
    href: '#law-minor-protection-62',
  },
  '民法典》诚实信用原则': {
    title: '中华人民共和国民法典',
    timeliness: '现行有效',
    approximate: true,
    href: '#law-civil-code-good-faith',
  },
};

const LAW_REF_PATTERN = /《([^》]+)》([^，。；|\n\s《》]*)/g;

function resolveLawRef(lawName: string, suffix: string): LawArticleRefMeta {
  const key = `${lawName}》${suffix}`;
  const registered = LAW_ARTICLE_REF_REGISTRY[key];
  if (registered) return registered;

  return {
    title: lawName.startsWith('中华人民共和国') ? lawName : `中华人民共和国${lawName}`,
    timeliness: '现行有效',
    approximate: lawName === '民法典',
  };
}

type LawArticleLinkProps = {
  meta: LawArticleRefMeta;
};

const LAW_LINK_CLASS =
  'no-underline underline-offset-2 hover:underline';

const APPROXIMATE_TOOLTIP_TEXT =
  '该法条为系统根据上下文近似识别结果，并非精确条号匹配。请结合原文和正式法规内容核对后使用。';

const ApproximateTag: React.FC = () => {
  const ref = useRef<HTMLSpanElement>(null);
  const [visible, setVisible] = useState(false);
  const [pos, setPos] = useState({ top: 0, left: 0 });

  const showTooltip = () => {
    const rect = ref.current?.getBoundingClientRect();
    if (rect) {
      const tooltipWidth = 300;
      const left = Math.min(Math.max(12, rect.left), window.innerWidth - tooltipWidth - 12);
      setPos({ top: rect.bottom + 8, left });
    }
    setVisible(true);
  };

  return (
    <>
      <span
        ref={ref}
        onMouseEnter={showTooltip}
        onMouseLeave={() => setVisible(false)}
        className="shrink-0 cursor-help rounded bg-amber-50 px-1 font-extrabold text-amber-600 ring-1 ring-amber-100/80"
      >
        近似识别
      </span>
      {visible
        ? createPortal(
            <div
              className="pointer-events-none fixed z-[2000] w-[min(300px,calc(100vw-24px))] rounded-xl border border-slate-200/90 bg-white p-3 text-[11px] font-medium leading-relaxed text-slate-600 shadow-lg shadow-slate-200/80"
              style={{ top: pos.top, left: pos.left }}
              role="tooltip"
            >
              {APPROXIMATE_TOOLTIP_TEXT}
            </div>,
            document.body
          )
        : null}
    </>
  );
};

export const LawArticleLink: React.FC<LawArticleLinkProps> = ({ meta }) => (
  <span className="mx-0.5 inline-flex max-w-full items-center gap-0.5 rounded-md bg-slate-100/90 px-1.5 py-0.5 align-middle text-[11px] leading-snug ring-1 ring-slate-200/60">
    <span className="shrink-0 font-bold text-slate-700">《</span>
    <a
      href={meta.href ?? '#'}
      className={`truncate font-extrabold text-blue-600 hover:text-blue-700 ${LAW_LINK_CLASS} decoration-blue-400/70`}
      onClick={(e) => e.preventDefault()}
    >
      {meta.title}
    </a>
    <span className="shrink-0 text-slate-300">|</span>
    <a
      href={meta.href ?? '#'}
      className={`shrink-0 font-extrabold text-teal-600 hover:text-teal-700 ${LAW_LINK_CLASS} decoration-teal-400/70`}
      onClick={(e) => e.preventDefault()}
    >
      {meta.timeliness}
    </a>
    {meta.approximate ? (
      <>
        <span className="shrink-0 text-slate-300">|</span>
        <ApproximateTag />
      </>
    ) : null}
    <span className="shrink-0 font-bold text-slate-700">》</span>
  </span>
);

export function parseLawRefsInText(text: string): React.ReactNode[] {
  const nodes: React.ReactNode[] = [];
  let lastIndex = 0;
  let match: RegExpExecArray | null;
  let key = 0;

  LAW_REF_PATTERN.lastIndex = 0;
  while ((match = LAW_REF_PATTERN.exec(text)) !== null) {
    const [full, lawName, suffix = ''] = match;
    if (match.index > lastIndex) {
      nodes.push(text.slice(lastIndex, match.index));
    }
    nodes.push(<LawArticleLink key={`law-${key++}`} meta={resolveLawRef(lawName, suffix)} />);
    lastIndex = match.index + full.length;
  }

  if (lastIndex < text.length) {
    nodes.push(text.slice(lastIndex));
  }

  return nodes.length > 0 ? nodes : [text];
}

export function enrichMarkdownChildren(children: React.ReactNode): React.ReactNode {
  return React.Children.map(children, (child) => {
    if (typeof child === 'string') {
      const parts = parseLawRefsInText(child);
      return parts.length === 1 && typeof parts[0] === 'string' ? parts[0] : <>{parts}</>;
    }
    if (React.isValidElement<{ children?: React.ReactNode }>(child) && child.props.children) {
      return React.cloneElement(child, {
        ...child.props,
        children: enrichMarkdownChildren(child.props.children),
      });
    }
    return child;
  });
}
