import React, { useEffect, useMemo, useRef, useState } from 'react';
import { Check, ChevronDown, ChevronLeft, ChevronRight, ClipboardList, Minus } from 'lucide-react';
import {
  OnboardingQuestion,
  PlaybookAnswers,
  REQUIRED_ONBOARDING_QUESTIONS,
  REVIEW_CHECKLISTS,
  buildDefaultChecklistAnswer,
  countFilledAnswers,
  getChecklistItemIds,
  getReviewChecklistById,
  hasAnyAnswer,
  type ReviewChecklistPoint,
} from './playbookOnboarding';

type AnswerValue = PlaybookAnswers[string];

const SUPPLEMENT_MAX_LEN = 300;

const emptyAnswer = (): AnswerValue => ({
  optionIds: [],
  customText: '',
  formValues: {},
  skipped: false,
});

function getAnswer(answers: PlaybookAnswers, qid: string): AnswerValue {
  return answers[qid] || emptyAnswer();
}

function ensureChecklistAnswer(answer?: AnswerValue): AnswerValue {
  if (answer?.formValues?.checklistId) {
    return {
      optionIds: answer.optionIds || [],
      customText: answer.customText || '',
      formValues: answer.formValues || {},
      skipped: false,
    };
  }
  return buildDefaultChecklistAnswer();
}

function ChecklistCheckbox({
  checked,
  indeterminate,
  onClick,
}: {
  checked: boolean;
  indeterminate?: boolean;
  onClick: () => void;
}) {
  return (
    <button
      type="button"
      onClick={(e) => {
        e.stopPropagation();
        onClick();
      }}
      className={`flex h-4 w-4 shrink-0 items-center justify-center rounded-[4px] border-[1.5px] transition-colors ${
        checked || indeterminate
          ? 'border-indigo-600 bg-indigo-600 text-white'
          : 'border-slate-300 bg-white'
      }`}
      aria-checked={indeterminate ? 'mixed' : checked}
      role="checkbox"
    >
      {indeterminate && !checked ? <Minus size={10} strokeWidth={3} /> : null}
      {checked ? <Check size={10} className="text-white" strokeWidth={3} /> : null}
    </button>
  );
}

function SectionLabel({ children }: { children: React.ReactNode }) {
  return (
    <div className="mb-2.5 flex items-center gap-2">
      <span className="h-3.5 w-1 rounded-full bg-indigo-500" />
      <span className="text-[13px] font-extrabold text-slate-800">{children}</span>
    </div>
  );
}

function ChecklistQuestionFields({
  answer,
  onChange,
}: {
  answer: AnswerValue;
  onChange: (next: AnswerValue) => void;
}) {
  const normalized = ensureChecklistAnswer(answer);
  const checklistId = normalized.formValues?.checklistId || '';
  const selectedChecklist = getReviewChecklistById(checklistId);
  const selectedIds = new Set(normalized.optionIds || []);
  const [expandedPointIds, setExpandedPointIds] = useState<string[]>(() =>
    selectedChecklist ? selectedChecklist.points.map((p) => p.id) : []
  );
  const [checklistMenuOpen, setChecklistMenuOpen] = useState(false);
  const checklistMenuRef = useRef<HTMLDivElement>(null);

  const totalItemCount = selectedChecklist ? getChecklistItemIds(selectedChecklist).length : 0;
  const selectedCount = selectedChecklist
    ? selectedChecklist.points.reduce(
        (sum, point) => sum + point.itemList.filter((item) => selectedIds.has(item.id)).length,
        0
      )
    : 0;

  useEffect(() => {
    if (!checklistMenuOpen) return undefined;
    const onPointerDown = (e: MouseEvent) => {
      if (checklistMenuRef.current && !checklistMenuRef.current.contains(e.target as Node)) {
        setChecklistMenuOpen(false);
      }
    };
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') setChecklistMenuOpen(false);
    };
    document.addEventListener('mousedown', onPointerDown);
    document.addEventListener('keydown', onKeyDown);
    return () => {
      document.removeEventListener('mousedown', onPointerDown);
      document.removeEventListener('keydown', onKeyDown);
    };
  }, [checklistMenuOpen]);

  const patch = (next: Partial<AnswerValue>) => {
    onChange({
      ...normalized,
      ...next,
      skipped: false,
    });
  };

  const handleSelectChecklist = (nextId: string) => {
    const list = getReviewChecklistById(nextId);
    if (!list) return;
    setExpandedPointIds(list.points.map((p) => p.id));
    setChecklistMenuOpen(false);
    patch({
      formValues: { checklistId: nextId },
      optionIds: getChecklistItemIds(list),
    });
  };

  const togglePoint = (point: ReviewChecklistPoint) => {
    const itemIds = point.itemList.map((item) => item.id);
    const allSelected = itemIds.every((id) => selectedIds.has(id));
    const next = new Set(selectedIds);
    if (allSelected) itemIds.forEach((id) => next.delete(id));
    else itemIds.forEach((id) => next.add(id));
    patch({ optionIds: Array.from(next) });
  };

  const toggleItem = (itemId: string) => {
    const next = new Set(selectedIds);
    if (next.has(itemId)) next.delete(itemId);
    else next.add(itemId);
    patch({ optionIds: Array.from(next) });
  };

  const toggleExpand = (pointId: string) => {
    setExpandedPointIds((prev) =>
      prev.includes(pointId) ? prev.filter((id) => id !== pointId) : [...prev, pointId]
    );
  };

  return (
    <div className="space-y-6">
      <div>
        <SectionLabel>请选择审查清单</SectionLabel>
        <div ref={checklistMenuRef} className="relative">
          <button
            type="button"
            onClick={() => setChecklistMenuOpen((open) => !open)}
            aria-haspopup="listbox"
            aria-expanded={checklistMenuOpen}
            className={`flex w-full items-center gap-3 rounded-2xl border bg-white px-4 py-3.5 text-left transition-all ${
              checklistMenuOpen
                ? 'border-indigo-300 shadow-md shadow-indigo-100 ring-4 ring-indigo-500/10'
                : 'border-slate-200 hover:border-indigo-200 hover:shadow-sm'
            }`}
          >
            <span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-indigo-50 text-indigo-600">
              <ClipboardList size={18} strokeWidth={2.5} />
            </span>
            <span className="min-w-0 flex-1">
              <span className="block truncate text-[14px] font-extrabold text-slate-800">
                {selectedChecklist?.name || '请选择审查清单'}
              </span>
              <span className="mt-0.5 block truncate text-[11px] font-medium text-slate-400">
                {selectedChecklist?.desc ||
                  (selectedChecklist
                    ? getChecklistItemIds(selectedChecklist).length > 0
                      ? `${selectedChecklist.points.length} 组审查点 · ${getChecklistItemIds(selectedChecklist).length} 项审查要求`
                      : '暂无审查点明细'
                    : '从系统清单中选择一份作为审查依据')}
              </span>
            </span>
            <ChevronDown
              size={18}
              className={`shrink-0 text-slate-400 transition-transform duration-200 ${
                checklistMenuOpen ? 'rotate-180 text-indigo-500' : ''
              }`}
              strokeWidth={2.5}
            />
          </button>

          {checklistMenuOpen ? (
            <div
              role="listbox"
              className="absolute left-0 right-0 top-[calc(100%+8px)] z-30 overflow-hidden rounded-2xl border border-slate-200/90 bg-white p-1.5 shadow-xl shadow-slate-200/80 animate-in fade-in zoom-in-95 duration-150 origin-top"
            >
              <div className="max-h-64 space-y-0.5 overflow-y-auto custom-scrollbar">
                {REVIEW_CHECKLISTS.map((list) => {
                  const selected = list.id === checklistId;
                  const pointCount = getChecklistItemIds(list).length;
                  return (
                    <button
                      key={list.id}
                      type="button"
                      role="option"
                      aria-selected={selected}
                      onClick={() => handleSelectChecklist(list.id)}
                      className={`flex w-full items-start gap-3 rounded-xl px-3 py-3 text-left transition-colors ${
                        selected
                          ? 'bg-indigo-50 text-indigo-700'
                          : 'text-slate-700 hover:bg-slate-50'
                      }`}
                    >
                      <span
                        className={`mt-0.5 flex h-5 w-5 shrink-0 items-center justify-center rounded-full border-2 ${
                          selected ? 'border-indigo-600 bg-indigo-600' : 'border-slate-300 bg-white'
                        }`}
                      >
                        {selected ? <Check size={11} className="text-white" strokeWidth={3} /> : null}
                      </span>
                      <span className="min-w-0 flex-1">
                        <span className="block text-[13px] font-extrabold leading-snug">
                          {list.name}
                        </span>
                        <span
                          className={`mt-1 block text-[11px] font-medium ${
                            selected ? 'text-indigo-400' : 'text-slate-400'
                          }`}
                        >
                          {pointCount > 0
                            ? `${list.points.length} 组审查点 · ${pointCount} 项审查要求`
                            : '暂无审查点明细'}
                        </span>
                      </span>
                    </button>
                  );
                })}
              </div>
            </div>
          ) : null}
        </div>
      </div>

      {selectedChecklist ? (
        <div>
          <div className="mb-2.5 flex items-center justify-between gap-3">
            <div className="flex items-center gap-2">
              <span className="h-3.5 w-1 rounded-full bg-indigo-500" />
              <span className="text-[13px] font-extrabold text-slate-800">请确认审查点</span>
            </div>
            <span className="text-[11px] font-bold text-slate-400">
              已选 {selectedCount} / {totalItemCount}
            </span>
          </div>
          {selectedChecklist.points.length === 0 ? (
            <div className="rounded-2xl border border-dashed border-slate-200 bg-slate-50 px-4 py-8 text-center text-[13px] font-medium text-slate-400">
              该审查清单暂无审查点数据，请先选择「通用条款审查精选清单」或等待接口接入
            </div>
          ) : (
            <div className="max-h-[360px] overflow-y-auto rounded-2xl border border-slate-200 bg-slate-50/70 p-2 custom-scrollbar">
              <div className="space-y-1">
                {selectedChecklist.points.map((point) => {
                  const itemIds = point.itemList.map((item) => item.id);
                  const selectedItemCount = itemIds.filter((id) => selectedIds.has(id)).length;
                  const allSelected = selectedItemCount === itemIds.length && itemIds.length > 0;
                  const partialSelected = selectedItemCount > 0 && !allSelected;
                  const expanded = expandedPointIds.includes(point.id);

                  return (
                    <div key={point.id} className="rounded-xl bg-white/80">
                      <div className="flex items-center gap-2 px-2.5 py-2.5">
                        <button
                          type="button"
                          onClick={() => toggleExpand(point.id)}
                          className="rounded-md p-0.5 text-slate-400 hover:bg-slate-100 hover:text-slate-600"
                          aria-label={expanded ? '收起' : '展开'}
                        >
                          {expanded ? (
                            <ChevronDown size={16} strokeWidth={2.5} />
                          ) : (
                            <ChevronRight size={16} strokeWidth={2.5} />
                          )}
                        </button>
                        <ChecklistCheckbox
                          checked={allSelected}
                          indeterminate={partialSelected}
                          onClick={() => togglePoint(point)}
                        />
                        <button
                          type="button"
                          onClick={() => toggleExpand(point.id)}
                          className="min-w-0 flex-1 text-left text-[13px] font-extrabold text-slate-800"
                        >
                          {point.pointName}
                        </button>
                      </div>
                      {expanded ? (
                        <div className="space-y-0.5 pb-2 pl-10 pr-2">
                          {point.itemList.map((item) => {
                            const selected = selectedIds.has(item.id);
                            return (
                              <button
                                key={item.id}
                                type="button"
                                onClick={() => toggleItem(item.id)}
                                className="flex w-full items-center gap-2.5 rounded-lg px-2 py-2 text-left transition-colors hover:bg-slate-50"
                              >
                                <ChecklistCheckbox checked={selected} onClick={() => toggleItem(item.id)} />
                                <span className="text-[13px] font-medium leading-relaxed text-slate-600">
                                  {item.reviewRequirement}
                                </span>
                              </button>
                            );
                          })}
                        </div>
                      ) : null}
                    </div>
                  );
                })}
              </div>
            </div>
          )}
        </div>
      ) : null}

      <div>
        <SectionLabel>添加补充信息</SectionLabel>
        <div className="relative">
          <textarea
            value={normalized.customText || ''}
            onChange={(e) =>
              patch({ customText: e.target.value.slice(0, SUPPLEMENT_MAX_LEN) })
            }
            rows={4}
            maxLength={SUPPLEMENT_MAX_LEN}
            placeholder="非必填，您还可以输入其他需要审查或提问的内容"
            className="w-full resize-none rounded-xl border border-slate-200 bg-white px-4 py-3 pb-8 text-[13px] font-medium leading-relaxed text-slate-700 outline-none transition-all placeholder:text-slate-400 focus:border-indigo-400 focus:ring-4 focus:ring-indigo-500/10"
          />
          <span className="pointer-events-none absolute bottom-3 right-3 text-[11px] font-bold text-slate-400">
            {(normalized.customText || '').length}/{SUPPLEMENT_MAX_LEN}
          </span>
        </div>
      </div>
    </div>
  );
}

type PlaybookOnboardingWizardProps = {
  mode: 'create' | 'edit';
  initialAnswers?: PlaybookAnswers;
  onCancel: () => void;
  onComplete: (answers: PlaybookAnswers) => void;
};

export default function PlaybookOnboardingWizard({
  mode,
  initialAnswers = {},
  onCancel,
  onComplete,
}: PlaybookOnboardingWizardProps) {
  const questions = REQUIRED_ONBOARDING_QUESTIONS;
  const [questionIndex, setQuestionIndex] = useState(0);
  const [draftAnswers, setDraftAnswers] = useState<PlaybookAnswers>(() => {
    const draft = JSON.parse(JSON.stringify(initialAnswers || {})) as PlaybookAnswers;
    draft.review_checklist = ensureChecklistAnswer(draft.review_checklist);
    return draft;
  });
  const [currentAnswer, setCurrentAnswer] = useState<AnswerValue>(() =>
    mode === 'edit' && initialAnswers[questions[0]?.id]
      ? {
          optionIds: initialAnswers[questions[0].id].optionIds || [],
          customText: initialAnswers[questions[0].id].customText || '',
          formValues: initialAnswers[questions[0].id].formValues || {},
          skipped: false,
        }
      : emptyAnswer()
  );

  const currentQuestion = questions[questionIndex];
  const isLastQuestion = questionIndex >= questions.length - 1;
  const progressPct = Math.round(((questionIndex + 1) / questions.length) * 100);
  const answeredCount = useMemo(() => countFilledAnswers(draftAnswers), [draftAnswers]);

  const loadAnswerForQuestion = (draft: PlaybookAnswers, qid: string) => {
    if (qid === 'review_checklist') return ensureChecklistAnswer(draft[qid]);
    const saved = draft[qid];
    if (!saved || saved.skipped) return emptyAnswer();
    return {
      optionIds: saved.optionIds || [],
      customText: saved.customText || '',
      formValues: saved.formValues || {},
      skipped: false,
    };
  };

  const syncCurrentIntoDraft = (answer: AnswerValue, qid: string) => ({
    ...draftAnswers,
    [qid]: answer,
  });

  const finish = (finalAnswers: PlaybookAnswers) => {
    if (mode === 'create' && !hasAnyAnswer(finalAnswers)) {
      onCancel();
      return;
    }
    onComplete(finalAnswers);
  };

  const canSubmitCurrent = (): boolean => {
    const q = currentQuestion;
    if (q.inputType === 'single') return (currentAnswer.optionIds?.length || 0) === 1;
    if (q.inputType === 'multi') {
      return (currentAnswer.optionIds?.length || 0) > 0 || !!(currentAnswer.customText || '').trim();
    }
    if (q.inputType === 'checklist') {
      return !!(currentAnswer.formValues?.checklistId && (currentAnswer.optionIds?.length || 0) > 0);
    }
    if (q.inputType === 'form') {
      const values = currentAnswer.formValues || {};
      const hasOptions =
        (currentAnswer.optionIds?.length || 0) > 0 || !!(currentAnswer.customText || '').trim();
      const hasForm = Object.values(values).some((v) => v && String(v).trim());
      return hasOptions || hasForm;
    }
    return false;
  };

  const handleNext = () => {
    if (!canSubmitCurrent()) return;
    const nextDraft = syncCurrentIntoDraft({ ...currentAnswer, skipped: false }, currentQuestion.id);
    setDraftAnswers(nextDraft);
    if (isLastQuestion) {
      finish(nextDraft);
      return;
    }
    const nextIndex = questionIndex + 1;
    setQuestionIndex(nextIndex);
    setCurrentAnswer(loadAnswerForQuestion(nextDraft, questions[nextIndex].id));
  };

  const handlePrev = () => {
    if (questionIndex <= 0) return;
    const nextDraft = syncCurrentIntoDraft({ ...currentAnswer, skipped: false }, currentQuestion.id);
    setDraftAnswers(nextDraft);
    const prevIndex = questionIndex - 1;
    setQuestionIndex(prevIndex);
    setCurrentAnswer(loadAnswerForQuestion(nextDraft, questions[prevIndex].id));
  };

  const handleSkip = () => {
    const nextDraft = syncCurrentIntoDraft({ ...emptyAnswer(), skipped: true }, currentQuestion.id);
    setDraftAnswers(nextDraft);
    if (isLastQuestion) {
      finish(nextDraft);
      return;
    }
    const nextIndex = questionIndex + 1;
    setQuestionIndex(nextIndex);
    setCurrentAnswer(loadAnswerForQuestion(nextDraft, questions[nextIndex].id));
  };

  const handleSkipAll = () => {
    const nextDraft = { ...draftAnswers };
    for (let i = questionIndex; i < questions.length; i++) {
      nextDraft[questions[i].id] = { ...emptyAnswer(), skipped: true };
    }
    finish(nextDraft);
  };

  const toggleMultiOption = (optionId: string) => {
    setCurrentAnswer((prev) => {
      const set = new Set(prev.optionIds || []);
      if (set.has(optionId)) set.delete(optionId);
      else set.add(optionId);
      return { ...prev, optionIds: Array.from(set), skipped: false };
    });
  };

  const setFormValue = (fieldId: string, value: string) => {
    setCurrentAnswer((prev) => ({
      ...prev,
      formValues: { ...(prev.formValues || {}), [fieldId]: value },
      skipped: false,
    }));
  };

  const renderFormMultiOptions = (q: OnboardingQuestion) => {
    if (!q.options?.length) return null;
    return (
      <div>
        <label className="mb-2 block text-[13px] font-bold text-slate-700">
          {q.optionsLabel || '可多选'}
        </label>
        <div className="space-y-2">
          {q.options.map((opt) => {
            const selected = (currentAnswer.optionIds || []).includes(opt.id);
            return (
              <button
                key={opt.id}
                type="button"
                onClick={() => toggleMultiOption(opt.id)}
                className={`flex w-full items-center gap-3 rounded-2xl border px-5 py-3.5 text-left transition-all ${
                  selected
                    ? 'border-indigo-300 bg-indigo-50 text-indigo-700 shadow-sm'
                    : 'border-slate-200 bg-white text-slate-700 hover:border-indigo-200 hover:bg-slate-50'
                }`}
              >
                <span
                  className={`flex h-5 w-5 shrink-0 items-center justify-center rounded-md border-2 ${
                    selected ? 'border-indigo-600 bg-indigo-600' : 'border-slate-300'
                  }`}
                >
                  {selected ? <Check size={12} className="text-white" strokeWidth={3} /> : null}
                </span>
                <span className="text-[14px] font-bold">{opt.label}</span>
              </button>
            );
          })}
        </div>
        {q.allowCustom ? (
          <input
            type="text"
            value={currentAnswer.customText || ''}
            onChange={(e) =>
              setCurrentAnswer((prev) => ({
                ...prev,
                customText: e.target.value,
                skipped: false,
              }))
            }
            placeholder={q.customPlaceholder || '其他（可选）'}
            className="mt-3 w-full rounded-2xl border border-slate-200 bg-white px-5 py-3.5 text-[14px] font-medium text-slate-700 outline-none focus:border-indigo-400 focus:ring-4 focus:ring-indigo-500/10"
          />
        ) : null}
      </div>
    );
  };

  /** 编辑模式：一页列出全部问题 */
  if (mode === 'edit') {
    const patchEditAnswer = (
      qid: string,
      patch: Partial<AnswerValue> | ((prev: AnswerValue) => AnswerValue)
    ) => {
      setDraftAnswers((prev) => {
        const current = getAnswer(prev, qid);
        const next = typeof patch === 'function' ? patch(current) : { ...current, ...patch, skipped: false };
        return { ...prev, [qid]: next };
      });
    };

    return (
      <div className="flex min-h-0 flex-1 flex-col animate-in slide-in-from-right-8 duration-300">
        <div className="custom-scrollbar flex-1 overflow-y-auto p-8">
          {questions.map((q) => {
            const answer = getAnswer(draftAnswers, q.id);
            return (
              <div
                key={q.id}
                className="mb-8 border-b border-slate-100 pb-8 last:mb-0 last:border-b-0 last:pb-0"
              >
                <h4 className="mb-1.5 text-[16px] font-extrabold leading-snug text-slate-800">
                  {q.title}
                </h4>
                {q.hint ? (
                  <p className="mb-4 text-[12px] font-medium text-slate-400">{q.hint}</p>
                ) : null}
                {q.inputType === 'single' ? (
                  <div className="space-y-2">
                    {q.options?.map((opt) => {
                      const selected = answer.optionIds?.[0] === opt.id;
                      return (
                        <button
                          key={opt.id}
                          type="button"
                          onClick={() => patchEditAnswer(q.id, { optionIds: [opt.id], skipped: false })}
                          className={`flex w-full items-center gap-3 rounded-2xl border px-4 py-3 text-left transition-all ${
                            selected
                              ? 'border-indigo-300 bg-indigo-50 text-indigo-700'
                              : 'border-slate-200 bg-white text-slate-700 hover:bg-slate-50'
                          }`}
                        >
                          <span
                            className={`flex h-5 w-5 shrink-0 items-center justify-center rounded-full border-2 ${
                              selected ? 'border-indigo-600 bg-indigo-600' : 'border-slate-300'
                            }`}
                          >
                            {selected ? (
                              <Check size={12} className="text-white" strokeWidth={3} />
                            ) : null}
                          </span>
                          <span className="text-[13px] font-bold">{opt.label}</span>
                        </button>
                      );
                    })}
                  </div>
                ) : null}
                {q.inputType === 'multi' ? (
                  <div className="space-y-2">
                    {q.options?.map((opt) => {
                      const selected = (answer.optionIds || []).includes(opt.id);
                      return (
                        <button
                          key={opt.id}
                          type="button"
                          onClick={() =>
                            patchEditAnswer(q.id, (prev) => {
                              const set = new Set(prev.optionIds || []);
                              if (set.has(opt.id)) set.delete(opt.id);
                              else set.add(opt.id);
                              return { ...prev, optionIds: Array.from(set), skipped: false };
                            })
                          }
                          className={`flex w-full items-center gap-3 rounded-2xl border px-4 py-3 text-left transition-all ${
                            selected
                              ? 'border-indigo-300 bg-indigo-50 text-indigo-700'
                              : 'border-slate-200 bg-white text-slate-700 hover:bg-slate-50'
                          }`}
                        >
                          <span
                            className={`flex h-5 w-5 shrink-0 items-center justify-center rounded-md border-2 ${
                              selected ? 'border-indigo-600 bg-indigo-600' : 'border-slate-300'
                            }`}
                          >
                            {selected ? (
                              <Check size={12} className="text-white" strokeWidth={3} />
                            ) : null}
                          </span>
                          <span className="text-[13px] font-bold">{opt.label}</span>
                        </button>
                      );
                    })}
                    {q.allowCustom ? (
                      <input
                        type="text"
                        value={answer.customText || ''}
                        onChange={(e) =>
                          patchEditAnswer(q.id, { customText: e.target.value, skipped: false })
                        }
                        placeholder={q.customPlaceholder || '其他（可选）'}
                        className="mt-2 w-full rounded-2xl border border-slate-200 px-4 py-3 text-[13px] font-medium outline-none focus:border-indigo-400 focus:ring-4 focus:ring-indigo-500/10"
                      />
                    ) : null}
                  </div>
                ) : null}
                {q.inputType === 'checklist' ? (
                  <ChecklistQuestionFields
                    answer={ensureChecklistAnswer(answer)}
                    onChange={(next) => patchEditAnswer(q.id, next)}
                  />
                ) : null}
                {q.inputType === 'form' ? (
                  <div className="space-y-4">
                    {q.optionsBeforeFields && q.options ? (
                      <div>
                        <label className="mb-2 block text-[12px] font-bold text-slate-700">
                          {q.optionsLabel || '可多选'}
                        </label>
                        <div className="space-y-2">
                          {q.options.map((opt) => {
                            const selected = (answer.optionIds || []).includes(opt.id);
                            return (
                              <button
                                key={opt.id}
                                type="button"
                                onClick={() =>
                                  patchEditAnswer(q.id, (prev) => {
                                    const set = new Set(prev.optionIds || []);
                                    if (set.has(opt.id)) set.delete(opt.id);
                                    else set.add(opt.id);
                                    return { ...prev, optionIds: Array.from(set), skipped: false };
                                  })
                                }
                                className={`flex w-full items-center gap-3 rounded-2xl border px-4 py-3 text-left ${
                                  selected
                                    ? 'border-indigo-300 bg-indigo-50 text-indigo-700'
                                    : 'border-slate-200 bg-white'
                                }`}
                              >
                                <span
                                  className={`flex h-5 w-5 items-center justify-center rounded-md border-2 ${
                                    selected ? 'border-indigo-600 bg-indigo-600' : 'border-slate-300'
                                  }`}
                                >
                                  {selected ? (
                                    <Check size={12} className="text-white" strokeWidth={3} />
                                  ) : null}
                                </span>
                                <span className="text-[13px] font-bold">{opt.label}</span>
                              </button>
                            );
                          })}
                        </div>
                        {q.allowCustom ? (
                          <input
                            type="text"
                            value={answer.customText || ''}
                            onChange={(e) =>
                              patchEditAnswer(q.id, {
                                customText: e.target.value,
                                skipped: false,
                              })
                            }
                            placeholder={q.customPlaceholder || '其他（可选）'}
                            className="mt-3 w-full rounded-2xl border border-slate-200 px-4 py-3 text-[13px] outline-none focus:border-indigo-400"
                          />
                        ) : null}
                      </div>
                    ) : null}
                    {q.formFields?.map((field) => (
                      <div key={field.id}>
                        <label className="mb-2 block text-[12px] font-bold text-slate-700">
                          {field.label}
                        </label>
                        {field.kind === 'select' ? (
                          <div className="space-y-2">
                            {field.options?.map((opt) => {
                              const selected = answer.formValues?.[field.id] === opt.id;
                              return (
                                <button
                                  key={opt.id}
                                  type="button"
                                  onClick={() =>
                                    patchEditAnswer(q.id, (prev) => ({
                                      ...prev,
                                      formValues: {
                                        ...(prev.formValues || {}),
                                        [field.id]: opt.id,
                                      },
                                      skipped: false,
                                    }))
                                  }
                                  className={`flex w-full items-center gap-3 rounded-2xl border px-4 py-3 text-left ${
                                    selected
                                      ? 'border-indigo-300 bg-indigo-50 text-indigo-700'
                                      : 'border-slate-200 bg-white'
                                  }`}
                                >
                                  <span
                                    className={`flex h-5 w-5 items-center justify-center rounded-full border-2 ${
                                      selected
                                        ? 'border-indigo-600 bg-indigo-600'
                                        : 'border-slate-300'
                                    }`}
                                  >
                                    {selected ? (
                                      <Check size={12} className="text-white" strokeWidth={3} />
                                    ) : null}
                                  </span>
                                  <span className="text-[13px] font-bold">{opt.label}</span>
                                </button>
                              );
                            })}
                          </div>
                        ) : (
                          <input
                            type="text"
                            value={answer.formValues?.[field.id] || ''}
                            onChange={(e) =>
                              patchEditAnswer(q.id, (prev) => ({
                                ...prev,
                                formValues: {
                                  ...(prev.formValues || {}),
                                  [field.id]: e.target.value,
                                },
                                skipped: false,
                              }))
                            }
                            placeholder={field.placeholder}
                            className="w-full rounded-2xl border border-slate-200 px-4 py-3 text-[13px] outline-none focus:border-indigo-400"
                          />
                        )}
                      </div>
                    ))}
                    {!q.optionsBeforeFields && q.options ? (
                      <div>
                        <label className="mb-2 block text-[12px] font-bold text-slate-700">
                          {q.optionsLabel || '可多选'}
                        </label>
                        <div className="space-y-2">
                          {q.options.map((opt) => {
                            const selected = (answer.optionIds || []).includes(opt.id);
                            return (
                              <button
                                key={opt.id}
                                type="button"
                                onClick={() =>
                                  patchEditAnswer(q.id, (prev) => {
                                    const set = new Set(prev.optionIds || []);
                                    if (set.has(opt.id)) set.delete(opt.id);
                                    else set.add(opt.id);
                                    return { ...prev, optionIds: Array.from(set), skipped: false };
                                  })
                                }
                                className={`flex w-full items-center gap-3 rounded-2xl border px-4 py-3 text-left ${
                                  selected
                                    ? 'border-indigo-300 bg-indigo-50 text-indigo-700'
                                    : 'border-slate-200 bg-white'
                                }`}
                              >
                                <span
                                  className={`flex h-5 w-5 items-center justify-center rounded-md border-2 ${
                                    selected ? 'border-indigo-600 bg-indigo-600' : 'border-slate-300'
                                  }`}
                                >
                                  {selected ? (
                                    <Check size={12} className="text-white" strokeWidth={3} />
                                  ) : null}
                                </span>
                                <span className="text-[13px] font-bold">{opt.label}</span>
                              </button>
                            );
                          })}
                        </div>
                      </div>
                    ) : null}
                  </div>
                ) : null}
              </div>
            );
          })}
        </div>
        <div className="flex shrink-0 items-center justify-end border-t border-slate-100 bg-white px-8 py-5">
          <button
            type="button"
            onClick={() => onComplete(draftAnswers)}
            className="rounded-2xl bg-indigo-600 px-10 py-3.5 font-bold text-white shadow-lg shadow-indigo-200 transition-all hover:bg-indigo-700 active:scale-95"
          >
            保存配置
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="flex min-h-0 flex-1 flex-col animate-in slide-in-from-right-8 duration-300">
      <div className="shrink-0 px-8 pt-6">
        <div className="mb-2 flex items-center justify-between">
          <span className="text-[12px] font-bold text-indigo-600">
            {questionIndex + 1} / {questions.length}
          </span>
          <span className="text-[12px] font-bold text-slate-400">{progressPct}%</span>
        </div>
        <div className="h-1.5 w-full overflow-hidden rounded-full bg-slate-100">
          <div className="h-full bg-indigo-600 transition-all duration-300" style={{ width: `${progressPct}%` }} />
        </div>
      </div>

      <div className="custom-scrollbar flex-1 overflow-y-auto p-8">
        <h4 className="mb-2 text-[18px] font-extrabold leading-snug text-slate-800">
          {currentQuestion.title}
        </h4>
        {currentQuestion.hint ? (
          <p className="mb-6 text-[13px] font-medium text-slate-400">{currentQuestion.hint}</p>
        ) : null}

        {currentQuestion.inputType === 'single' ? (
          <div className="space-y-3">
            {currentQuestion.options?.map((opt) => {
              const selected = currentAnswer.optionIds?.[0] === opt.id;
              return (
                <button
                  key={opt.id}
                  type="button"
                  onClick={() =>
                    setCurrentAnswer({ optionIds: [opt.id], customText: '', formValues: {}, skipped: false })
                  }
                  className={`flex w-full items-center gap-3 rounded-2xl border px-5 py-4 text-left transition-all ${
                    selected
                      ? 'border-indigo-300 bg-indigo-50 text-indigo-700 shadow-sm'
                      : 'border-slate-200 bg-white text-slate-700 hover:border-indigo-200 hover:bg-slate-50'
                  }`}
                >
                  <span
                    className={`flex h-5 w-5 shrink-0 items-center justify-center rounded-full border-2 ${
                      selected ? 'border-indigo-600 bg-indigo-600' : 'border-slate-300'
                    }`}
                  >
                    {selected ? <Check size={12} className="text-white" strokeWidth={3} /> : null}
                  </span>
                  <span className="text-[14px] font-bold leading-relaxed">{opt.label}</span>
                </button>
              );
            })}
          </div>
        ) : null}

        {currentQuestion.inputType === 'multi' ? (
          <div className="space-y-3">
            {currentQuestion.options?.map((opt) => {
              const selected = (currentAnswer.optionIds || []).includes(opt.id);
              return (
                <button
                  key={opt.id}
                  type="button"
                  onClick={() => toggleMultiOption(opt.id)}
                  className={`flex w-full items-center gap-3 rounded-2xl border px-5 py-4 text-left transition-all ${
                    selected
                      ? 'border-indigo-300 bg-indigo-50 text-indigo-700 shadow-sm'
                      : 'border-slate-200 bg-white text-slate-700 hover:border-indigo-200 hover:bg-slate-50'
                  }`}
                >
                  <span
                    className={`flex h-5 w-5 shrink-0 items-center justify-center rounded-md border-2 ${
                      selected ? 'border-indigo-600 bg-indigo-600' : 'border-slate-300'
                    }`}
                  >
                    {selected ? <Check size={12} className="text-white" strokeWidth={3} /> : null}
                  </span>
                  <span className="text-[14px] font-bold leading-relaxed">{opt.label}</span>
                </button>
              );
            })}
            {currentQuestion.allowCustom ? (
              <input
                type="text"
                value={currentAnswer.customText || ''}
                onChange={(e) =>
                  setCurrentAnswer((prev) => ({
                    ...prev,
                    customText: e.target.value,
                    skipped: false,
                  }))
                }
                placeholder={currentQuestion.customPlaceholder || '其他（可选）'}
                className="mt-2 w-full rounded-2xl border border-slate-200 px-5 py-3.5 text-[14px] font-medium outline-none focus:border-indigo-400 focus:ring-4 focus:ring-indigo-500/10"
              />
            ) : null}
          </div>
        ) : null}

        {currentQuestion.inputType === 'checklist' ? (
          <ChecklistQuestionFields
            answer={ensureChecklistAnswer(currentAnswer)}
            onChange={setCurrentAnswer}
          />
        ) : null}

        {currentQuestion.inputType === 'form' ? (
          <div className="space-y-5">
            {currentQuestion.optionsBeforeFields ? renderFormMultiOptions(currentQuestion) : null}
            {currentQuestion.formFields?.map((field) => (
              <div key={field.id}>
                <label className="mb-2 block text-[13px] font-bold text-slate-700">{field.label}</label>
                {field.kind === 'select' ? (
                  <div className="space-y-2">
                    {field.options?.map((opt) => {
                      const selected = currentAnswer.formValues?.[field.id] === opt.id;
                      return (
                        <button
                          key={opt.id}
                          type="button"
                          onClick={() => setFormValue(field.id, opt.id)}
                          className={`flex w-full items-center gap-3 rounded-2xl border px-5 py-3.5 text-left transition-all ${
                            selected
                              ? 'border-indigo-300 bg-indigo-50 text-indigo-700'
                              : 'border-slate-200 bg-white hover:bg-slate-50'
                          }`}
                        >
                          <span
                            className={`flex h-5 w-5 items-center justify-center rounded-full border-2 ${
                              selected ? 'border-indigo-600 bg-indigo-600' : 'border-slate-300'
                            }`}
                          >
                            {selected ? (
                              <Check size={12} className="text-white" strokeWidth={3} />
                            ) : null}
                          </span>
                          <span className="text-[14px] font-bold">{opt.label}</span>
                        </button>
                      );
                    })}
                  </div>
                ) : (
                  <input
                    type="text"
                    value={currentAnswer.formValues?.[field.id] || ''}
                    onChange={(e) => setFormValue(field.id, e.target.value)}
                    placeholder={field.placeholder}
                    className="w-full rounded-2xl border border-slate-200 px-5 py-3.5 text-[14px] outline-none focus:border-indigo-400 focus:ring-4 focus:ring-indigo-500/10"
                  />
                )}
              </div>
            ))}
            {!currentQuestion.optionsBeforeFields ? renderFormMultiOptions(currentQuestion) : null}
          </div>
        ) : null}
      </div>

      <div className="flex shrink-0 items-center justify-between gap-3 border-t border-slate-100 bg-white px-8 py-5">
        <div className="flex items-center gap-2">
          <button
            type="button"
            onClick={handleSkip}
            className="rounded-xl px-4 py-2.5 text-[13px] font-bold text-slate-500 hover:bg-slate-50 hover:text-slate-700"
          >
            跳过此题
          </button>
          <button
            type="button"
            onClick={handleSkipAll}
            className="rounded-xl px-4 py-2.5 text-[13px] font-bold text-slate-400 hover:bg-slate-50"
          >
            全部跳过
          </button>
          {answeredCount > 0 ? (
            <span className="ml-1 text-[11px] font-bold text-indigo-500">已答 {answeredCount} 题</span>
          ) : null}
        </div>
        <div className="flex items-center gap-2">
          {questionIndex > 0 ? (
            <button
              type="button"
              onClick={handlePrev}
              className="flex items-center gap-1.5 rounded-2xl border border-slate-200 px-6 py-3.5 font-bold text-slate-600 hover:bg-slate-50"
            >
              <ChevronLeft size={18} strokeWidth={2.5} />
              上一题
            </button>
          ) : null}
          <button
            type="button"
            onClick={handleNext}
            disabled={!canSubmitCurrent()}
            className={`flex items-center gap-2 rounded-2xl px-8 py-3.5 font-bold transition-all ${
              canSubmitCurrent()
                ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-200 hover:bg-indigo-700 active:scale-95'
                : 'cursor-not-allowed border border-slate-200 bg-slate-100 text-slate-400'
            }`}
          >
            {isLastQuestion ? '完成并创建' : '下一题'}
            {!isLastQuestion ? <ChevronRight size={18} strokeWidth={2.5} /> : null}
          </button>
        </div>
      </div>
    </div>
  );
}
