import { FILTER_BASED_TURN_PROMPT, type ConversationTurn } from './conversationTurns';
import type { ReferenceSourceItem } from './mockSearchResult';

export type ReportSourceScope = 'cited' | 'all_turn' | 'filtered';

export function resolveTurnUserQuestion(
  turn: ConversationTurn,
  submittedQuery: string
): string {
  if (turn.kind === 'follow_up' && turn.userPrompt && turn.userPrompt !== FILTER_BASED_TURN_PROMPT) {
    return turn.userPrompt;
  }
  return submittedQuery.trim() || '当前检索问题';
}

export function getTurnReferenceSources(
  turn: ConversationTurn,
  allSources: ReferenceSourceItem[]
): ReferenceSourceItem[] {
  const idSet = new Set(turn.sourceIds);
  return allSources.filter((s) => idSet.has(s.id));
}

export function getTurnCitedSources(sources: ReferenceSourceItem[]): ReferenceSourceItem[] {
  return sources.filter((s) => !!s.citedMark);
}

export function defaultReportSourceScope(citedSources: ReferenceSourceItem[]): ReportSourceScope {
  return citedSources.length > 0 ? 'cited' : 'all_turn';
}

export function resolveReportSources(
  scope: ReportSourceScope,
  citedSources: ReferenceSourceItem[],
  allTurnSources: ReferenceSourceItem[],
  filteredSources: ReferenceSourceItem[] | null
): ReferenceSourceItem[] {
  if (scope === 'cited') return citedSources;
  if (scope === 'filtered' && filteredSources) return filteredSources;
  return allTurnSources;
}
