import React, { useMemo, useState } from 'react';
import {
  Check,
  ChevronRight,
  FileText,
  Folder,
  Link as LinkIcon,
  Sparkles,
} from 'lucide-react';

export type WorkspacePickerSource = {
  id: string | number;
  title: string;
  type?: string;
  date?: string;
  status?: string;
};

export type WorkspacePickerConclusion = {
  id: string | number;
  title: string;
  type?: string;
  status?: string;
  completedAt?: string;
};

export type WorkspaceFileSelection = {
  origin: 'source' | 'conclusion';
  id: string | number;
  title: string;
};

export type WorkspaceFilePickerAccent = 'rose' | 'indigo' | 'sky';

type FolderKey = 'root' | 'sources' | 'conclusions';

type WorkspaceFilePickerProps = {
  sources: WorkspacePickerSource[];
  conclusions: WorkspacePickerConclusion[];
  selected: WorkspaceFileSelection[];
  onToggle: (file: WorkspaceFileSelection) => void;
  /** 已达上限时禁止新增选择（仍可取消已选） */
  disableAdd?: boolean;
  /** 主色：脱敏 rose（默认），合同审查 indigo，制度合规 sky */
  accent?: WorkspaceFilePickerAccent;
  /** 文件夹计数文案，如「可脱敏文件」「可选文件」 */
  selectableCountLabel?: string;
  emptySourcesText?: string;
  emptyConclusionsText?: string;
};

export function isSameWorkspaceSelection(
  a: WorkspaceFileSelection,
  b: WorkspaceFileSelection
): boolean {
  return a.origin === b.origin && String(a.id) === String(b.id);
}

const FOLDER_META: Record<
  Exclude<FolderKey, 'root'>,
  { label: string; pathLabel: string }
> = {
  sources: { label: '来源文件', pathLabel: '来源文件' },
  conclusions: { label: '生成结果', pathLabel: '生成结果' },
};

/** 可作为脱敏/审查对象的来源文件类型（排除链接/法宝等非文件） */
const SOURCE_FILE_TYPES = new Set(['pdf', 'doc', 'docx', 'txt']);

export function isDesensitizableSource(source: WorkspacePickerSource): boolean {
  if (!source?.type || !SOURCE_FILE_TYPES.has(source.type)) return false;
  if (source.status === 'parsing') return false;
  return true;
}

export function isDesensitizableConclusion(conclusion: WorkspacePickerConclusion): boolean {
  return conclusion?.status === 'completed';
}

const ACCENT_STYLES: Record<
  WorkspaceFilePickerAccent,
  {
    breadcrumbLink: string;
    folderHover: string;
    selectedRow: string;
    selectedIconWrap: string;
    checkBg: string;
    sparkles: string;
  }
> = {
  rose: {
    breadcrumbLink: 'text-rose-600 hover:underline',
    folderHover: 'hover:bg-rose-50/70',
    selectedRow: 'bg-rose-50 ring-1 ring-rose-200',
    selectedIconWrap: 'bg-white text-rose-600',
    checkBg: 'bg-rose-600',
    sparkles: 'text-rose-500',
  },
  indigo: {
    breadcrumbLink: 'text-indigo-600 hover:underline',
    folderHover: 'hover:bg-indigo-50/70',
    selectedRow: 'bg-indigo-50 ring-1 ring-indigo-200',
    selectedIconWrap: 'bg-white text-indigo-600',
    checkBg: 'bg-indigo-600',
    sparkles: 'text-indigo-500',
  },
  sky: {
    breadcrumbLink: 'text-sky-600 hover:underline',
    folderHover: 'hover:bg-sky-50/70',
    selectedRow: 'bg-sky-50 ring-1 ring-sky-200',
    selectedIconWrap: 'bg-white text-sky-600',
    checkBg: 'bg-sky-600',
    sparkles: 'text-sky-500',
  },
};

function fileTypeIcon(type: string | undefined, accent: WorkspaceFilePickerAccent) {
  if (type === 'url' || type === 'fb') {
    return <LinkIcon size={16} className="text-blue-500" strokeWidth={2.5} />;
  }
  if (
    type === '核心争议' ||
    type === '报告生成' ||
    type === '抗辩策略' ||
    type === '类案检索' ||
    type === '自定义文档' ||
    type === '合同审查' ||
    type === '制度合规审查'
  ) {
    return (
      <Sparkles size={16} className={ACCENT_STYLES[accent].sparkles} strokeWidth={2.5} />
    );
  }
  return <FileText size={16} className="text-slate-500" strokeWidth={2.5} />;
}

const WorkspaceFilePicker: React.FC<WorkspaceFilePickerProps> = ({
  sources,
  conclusions,
  selected,
  onToggle,
  disableAdd = false,
  accent = 'rose',
  selectableCountLabel = '可脱敏文件',
  emptySourcesText = '暂无可脱敏的来源文件（仅支持已就绪的文档类文件）',
  emptyConclusionsText = '暂无可脱敏的生成结果（仅支持已完成的结果）',
}) => {
  const [folder, setFolder] = useState<FolderKey>('root');
  const selectedList = selected || [];
  const styles = ACCENT_STYLES[accent];

  const selectableSources = useMemo(
    () => sources.filter(isDesensitizableSource),
    [sources]
  );
  const selectableConclusions = useMemo(
    () => conclusions.filter(isDesensitizableConclusion),
    [conclusions]
  );

  const breadcrumb = useMemo(() => {
    if (folder === 'root') return ['工作空间文件'];
    return ['工作空间文件', FOLDER_META[folder].pathLabel];
  }, [folder]);

  const files = useMemo(() => {
    if (folder === 'sources') {
      return selectableSources.map((s) => ({
        id: s.id,
        title: s.title,
        type: s.type,
        meta: s.date,
        origin: 'source' as const,
      }));
    }
    if (folder === 'conclusions') {
      return selectableConclusions.map((c) => ({
        id: c.id,
        title: c.title,
        type: c.type,
        meta: c.completedAt || '已完成',
        origin: 'conclusion' as const,
      }));
    }
    return [];
  }, [folder, selectableSources, selectableConclusions]);

  return (
    <div className="flex h-full min-h-0 flex-col overflow-hidden rounded-2xl border border-slate-200 bg-white">
      <div className="flex shrink-0 items-center gap-1.5 border-b border-slate-100 bg-slate-50/80 px-4 py-2.5">
        {breadcrumb.map((seg, idx) => {
          const isLast = idx === breadcrumb.length - 1;
          const canJumpRoot = idx === 0 && folder !== 'root';
          return (
            <React.Fragment key={`${seg}-${idx}`}>
              {idx > 0 ? <ChevronRight size={14} className="shrink-0 text-slate-300" /> : null}
              <button
                type="button"
                disabled={!canJumpRoot && !isLast}
                onClick={() => {
                  if (canJumpRoot) setFolder('root');
                }}
                className={`max-w-[180px] truncate text-[12px] font-bold ${
                  isLast
                    ? 'text-slate-700'
                    : canJumpRoot
                      ? styles.breadcrumbLink
                      : 'text-slate-400'
                }`}
              >
                {seg}
              </button>
            </React.Fragment>
          );
        })}
      </div>

      <div className="custom-scrollbar min-h-0 flex-1 overflow-y-auto p-2">
        {folder === 'root' ? (
          <div className="space-y-1">
            {(Object.keys(FOLDER_META) as Array<keyof typeof FOLDER_META>).map((key) => {
              const count =
                key === 'sources' ? selectableSources.length : selectableConclusions.length;
              return (
                <button
                  key={key}
                  type="button"
                  onClick={() => setFolder(key)}
                  className={`group flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left transition-colors ${styles.folderHover}`}
                >
                  <span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-amber-50 text-amber-600 group-hover:bg-amber-100">
                    <Folder size={18} strokeWidth={2.5} />
                  </span>
                  <div className="min-w-0 flex-1">
                    <div className="text-[13px] font-bold text-slate-800">
                      {FOLDER_META[key].label}
                    </div>
                    <div className="mt-0.5 text-[11px] font-medium text-slate-400">
                      {count} 个{selectableCountLabel}
                    </div>
                  </div>
                  <ChevronRight size={16} className="shrink-0 text-slate-300" />
                </button>
              );
            })}
          </div>
        ) : files.length === 0 ? (
          <div className="px-3 py-10 text-center text-[12px] font-medium leading-relaxed text-slate-400">
            {folder === 'sources' ? emptySourcesText : emptyConclusionsText}
          </div>
        ) : (
          <div className="space-y-1">
            {files.map((file) => {
              const selection = { origin: file.origin, id: file.id, title: file.title };
              const isSelected = selectedList.some((s) => isSameWorkspaceSelection(s, selection));
              const blocked = !isSelected && disableAdd;
              return (
                <button
                  key={`${file.origin}-${file.id}`}
                  type="button"
                  disabled={blocked}
                  onClick={() => onToggle(selection)}
                  className={`flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left transition-colors ${
                    isSelected
                      ? styles.selectedRow
                      : blocked
                        ? 'cursor-not-allowed opacity-40'
                        : 'hover:bg-slate-50'
                  }`}
                >
                  <span
                    className={`flex h-9 w-9 shrink-0 items-center justify-center rounded-xl ${
                      isSelected ? styles.selectedIconWrap : 'bg-slate-50'
                    }`}
                  >
                    {fileTypeIcon(file.type, accent)}
                  </span>
                  <div className="min-w-0 flex-1">
                    <div className="truncate text-[13px] font-bold text-slate-800">{file.title}</div>
                    {file.meta ? (
                      <div className="mt-0.5 truncate text-[11px] font-medium text-slate-400">
                        {file.meta}
                      </div>
                    ) : null}
                  </div>
                  {isSelected ? (
                    <span
                      className={`flex h-5 w-5 shrink-0 items-center justify-center rounded-md text-white ${styles.checkBg}`}
                    >
                      <Check size={12} strokeWidth={3} />
                    </span>
                  ) : null}
                </button>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
};

export default WorkspaceFilePicker;
