import React, { useEffect, useMemo } from 'react';
import type {
  AnnotatedWordBlock,
  AnnotatedWordDocument,
  AnnotatedWordSegment,
  ReviewCommentSeverity,
} from './mockAnnotatedWord';

type Props = {
  document: AnnotatedWordDocument;
  /** 批注 id（c*）或修订 id（r*） */
  activeItemId?: string | null;
};

const SEVERITY_MARK: Record<ReviewCommentSeverity, string> = {
  严重: 'bg-red-100/90 decoration-red-400',
  高: 'bg-amber-100/90 decoration-amber-400',
  中: 'bg-yellow-100/80 decoration-yellow-400',
  低: 'bg-slate-100 decoration-slate-300',
};

function severityOf(
  commentIds: string[],
  severityById: Map<string, ReviewCommentSeverity>
): ReviewCommentSeverity | null {
  if (!commentIds.length) return null;
  const order: ReviewCommentSeverity[] = ['严重', '高', '中', '低'];
  let best: ReviewCommentSeverity | null = null;
  commentIds.forEach((id) => {
    const s = severityById.get(id);
    if (!s) return;
    if (!best || order.indexOf(s) < order.indexOf(best)) best = s;
  });
  return best;
}

function SegmentView({
  segment,
  severityById,
  activeItemId,
  commentIndexById,
  revisionIndexById,
}: {
  segment: AnnotatedWordSegment;
  severityById: Map<string, ReviewCommentSeverity>;
  activeItemId?: string | null;
  commentIndexById: Map<string, number>;
  revisionIndexById: Map<string, number>;
}) {
  const sev = severityOf(segment.commentIds, severityById);
  const isCommentActive =
    !!activeItemId && segment.commentIds.includes(activeItemId);
  const isRevisionActive =
    !!activeItemId && !!segment.revisionId && segment.revisionId === activeItemId;
  const isActive = isCommentActive || isRevisionActive;
  const firstCommentId = segment.commentIds[0];
  const badgeNo = firstCommentId ? commentIndexById.get(firstCommentId) : undefined;
  const revNo = segment.revisionId
    ? revisionIndexById.get(segment.revisionId)
    : undefined;

  if (segment.type === 'del') {
    return (
      <span
        data-revision-id={segment.revisionId}
        data-comment-ids={segment.commentIds.join(' ')}
        className={`mx-0.5 text-red-600 line-through decoration-red-400 transition-shadow duration-200 ${
          isActive ? 'bg-red-50 shadow-[0_0_0_3px_rgba(239,68,68,0.25)]' : ''
        }`}
      >
        {segment.text}
        {revNo != null && segment.revisionId ? (
          <sup className="ml-0.5 align-super text-[10px] font-extrabold text-blue-600 no-underline">
            [R{revNo}]
          </sup>
        ) : null}
      </span>
    );
  }

  if (segment.type === 'ins') {
    return (
      <span
        data-revision-id={segment.revisionId}
        data-comment-ids={segment.commentIds.join(' ')}
        className={`mx-0.5 font-semibold text-blue-700 underline decoration-blue-400 decoration-2 underline-offset-2 transition-shadow duration-200 ${
          isActive ? 'bg-blue-50 shadow-[0_0_0_3px_rgba(37,99,235,0.28)]' : ''
        }`}
      >
        {segment.text}
        {revNo != null && segment.revisionId ? (
          <sup className="ml-0.5 align-super text-[10px] font-extrabold text-blue-600 no-underline">
            [R{revNo}]
          </sup>
        ) : null}
      </span>
    );
  }

  if (!sev) {
    return <>{segment.text}</>;
  }

  return (
    <mark
      data-comment-id={firstCommentId}
      data-comment-ids={segment.commentIds.join(' ')}
      className={`relative rounded-[2px] px-0.5 font-semibold text-slate-800 transition-shadow duration-200 ${
        SEVERITY_MARK[sev]
      } ${
        isActive
          ? 'shadow-[0_0_0_3px_rgba(79,70,229,0.28)] ring-1 ring-indigo-300'
          : ''
      }`}
      title="审查批注"
    >
      {segment.text}
      {badgeNo != null ? (
        <sup className="ml-0.5 align-super text-[10px] font-extrabold text-indigo-600">
          [{badgeNo}]
        </sup>
      ) : null}
    </mark>
  );
}

function BlockView({
  block,
  severityById,
  activeItemId,
  commentIndexById,
  revisionIndexById,
}: {
  block: AnnotatedWordBlock;
  severityById: Map<string, ReviewCommentSeverity>;
  activeItemId?: string | null;
  commentIndexById: Map<string, number>;
  revisionIndexById: Map<string, number>;
}) {
  if (block.style === 'sign-table') {
    return (
      <table className="mt-10 w-full border-collapse text-[13px] text-slate-700">
        <tbody>
          {block.rows.map((row, ri) => (
            <tr key={ri}>
              {row.map((cell, ci) => (
                <td
                  key={ci}
                  className="w-1/2 border border-slate-200 px-3 py-2.5 align-top font-medium leading-relaxed"
                >
                  {cell || '\u00a0'}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    );
  }

  const className =
    block.style === 'title'
      ? 'mb-8 text-center text-[22px] font-extrabold tracking-wide text-slate-900'
      : block.style === 'article'
        ? 'mb-3 mt-7 text-[15px] font-extrabold text-slate-900'
        : block.style === 'party'
          ? 'mb-1 text-[13.5px] font-bold text-slate-700'
          : 'mb-2.5 text-[13.5px] font-medium leading-[1.85] text-slate-700';

  return (
    <p className={className}>
      {block.segments.map((seg, i) => (
        <SegmentView
          key={`${seg.type}-${i}-${seg.text.slice(0, 12)}`}
          segment={seg}
          severityById={severityById}
          activeItemId={activeItemId}
          commentIndexById={commentIndexById}
          revisionIndexById={revisionIndexById}
        />
      ))}
    </p>
  );
}

/**
 * 合同审查交付物预览：模拟带批注 / 红线修订的 Word 文档中间区
 */
export default function ContractReviewWordPreview({
  document,
  activeItemId,
}: Props) {
  const severityById = useMemo(() => {
    const map = new Map<string, ReviewCommentSeverity>();
    document.comments.forEach((c) => map.set(c.id, c.severity));
    return map;
  }, [document.comments]);

  const commentIndexById = useMemo(() => {
    const map = new Map<string, number>();
    document.comments.forEach((c, i) => map.set(c.id, i + 1));
    return map;
  }, [document.comments]);

  const revisionIndexById = useMemo(() => {
    const map = new Map<string, number>();
    (document.revisions || []).forEach((r, i) => map.set(r.id, i + 1));
    return map;
  }, [document.revisions]);

  useEffect(() => {
    if (!activeItemId) return;
    const el = (
      activeItemId.startsWith('r')
        ? window.document.querySelector(`[data-revision-id="${activeItemId}"]`)
        : window.document.querySelector(`[data-comment-id="${activeItemId}"]`)
    ) as HTMLElement | null;
    el?.scrollIntoView({ behavior: 'smooth', block: 'center' });
  }, [activeItemId]);

  return (
    <div className="w-full max-w-[820px] shrink-0">
      <article className="min-h-[1100px] rounded-sm border border-gray-200 bg-white px-12 py-14 shadow-md sm:px-16 sm:py-16 lg:px-20 lg:py-20">
        {document.blocks.map((block, index) => (
          <BlockView
            key={index}
            block={block}
            severityById={severityById}
            activeItemId={activeItemId}
            commentIndexById={commentIndexById}
            revisionIndexById={revisionIndexById}
          />
        ))}
      </article>
    </div>
  );
}
