import React, { useMemo, useState } from 'react';
import { ChevronDown, MessageSquareText } from 'lucide-react';
import type {
  AnnotatedWordDocument,
  AnnotatedWordRevisionKind,
  ReviewCommentSeverity,
  ReviewResultItem,
} from './mockAnnotatedWord';
import {
  buildReviewResultItems,
  countCommentsBySeverity,
} from './mockAnnotatedWord';

type FilterKey = '全部' | '批注' | '修订' | ReviewCommentSeverity;

type Props = {
  document: AnnotatedWordDocument;
  open: boolean;
  activeItemId?: string | null;
  onToggle: () => void;
  onSelectItem: (itemId: string) => void;
};

const SEVERITY_ORDER: ReviewCommentSeverity[] = ['严重', '高', '中', '低'];

const SEVERITY_STYLE: Record<
  ReviewCommentSeverity,
  { badge: string; dot: string }
> = {
  严重: { badge: 'bg-red-50 text-red-600 ring-red-200', dot: 'bg-red-500' },
  高: { badge: 'bg-amber-50 text-amber-700 ring-amber-200', dot: 'bg-amber-500' },
  中: { badge: 'bg-yellow-50 text-yellow-700 ring-yellow-200', dot: 'bg-yellow-500' },
  低: { badge: 'bg-slate-50 text-slate-600 ring-slate-200', dot: 'bg-slate-400' },
};

function revisionLabel(kind: AnnotatedWordRevisionKind) {
  if (kind === 'replace') return '替换';
  if (kind === 'insert') return '新增';
  return '删除';
}

/**
 * 中间预览右下角：审查结果浮层（批注 + Word 修订）
 */
export default function ContractReviewCommentsFloat({
  document,
  open,
  activeItemId,
  onToggle,
  onSelectItem,
}: Props) {
  const [filter, setFilter] = useState<FilterKey>('全部');
  const items = useMemo(() => buildReviewResultItems(document), [document]);
  const comments = useMemo(
    () => items.filter((i): i is Extract<ReviewResultItem, { kind: 'comment' }> => i.kind === 'comment'),
    [items]
  );
  const revisions = useMemo(
    () => items.filter((i): i is Extract<ReviewResultItem, { kind: 'revision' }> => i.kind === 'revision'),
    [items]
  );
  const severityCounts = useMemo(() => countCommentsBySeverity(document.comments), [document.comments]);

  const filtered = useMemo(() => {
    if (filter === '全部') return items;
    if (filter === '批注') return comments;
    if (filter === '修订') return revisions;
    return comments.filter((c) => c.severity === filter);
  }, [filter, items, comments, revisions]);

  const totalCount = items.length;

  return (
    <div className="pointer-events-none absolute bottom-5 right-4 z-[35] flex flex-col items-end gap-2 md:bottom-6 md:right-6">
      {open ? (
        <div className="pointer-events-auto flex w-[340px] max-h-[min(540px,72vh)] flex-col overflow-hidden rounded-2xl border border-slate-200/90 bg-white/95 shadow-xl shadow-slate-400/20 backdrop-blur-md animate-in fade-in slide-in-from-bottom-2 duration-200">
          <div className="flex shrink-0 items-center justify-between gap-2 border-b border-slate-100 px-3.5 py-2.5">
            <div className="min-w-0">
              <div className="text-[13px] font-extrabold text-slate-800">审查结果</div>
              <div className="mt-0.5 text-[11px] font-medium text-slate-400">
                批注 {comments.length} · 修订 {revisions.length}
              </div>
            </div>
            <button
              type="button"
              onClick={onToggle}
              className="rounded-lg p-1.5 text-slate-400 transition hover:bg-slate-100 hover:text-slate-600"
              aria-label="收起审查结果"
            >
              <ChevronDown size={16} strokeWidth={2.5} />
            </button>
          </div>

          <div className="flex shrink-0 gap-1 overflow-x-auto px-2.5 py-2 no-scrollbar">
            <FilterChip
              label="全部"
              count={totalCount}
              active={filter === '全部'}
              onClick={() => setFilter('全部')}
            />
            <FilterChip
              label="批注"
              count={comments.length}
              active={filter === '批注'}
              onClick={() => setFilter('批注')}
            />
            <FilterChip
              label="修订"
              count={revisions.length}
              active={filter === '修订'}
              onClick={() => setFilter('修订')}
            />
            {SEVERITY_ORDER.filter((s) => severityCounts[s] > 0).map((s) => (
              <FilterChip
                key={s}
                label={s}
                count={severityCounts[s]}
                active={filter === s}
                onClick={() => setFilter(s)}
              />
            ))}
          </div>

          <div className="custom-scrollbar min-h-0 flex-1 overflow-y-auto px-2 pb-2">
            {filtered.length === 0 ? (
              <div className="px-2 py-8 text-center text-[12px] font-medium text-slate-400">
                暂无结果
              </div>
            ) : (
              <div className="space-y-1">
                {filtered.map((item) => {
                  const active = activeItemId === item.id;
                  if (item.kind === 'revision') {
                    const idx = revisions.findIndex((r) => r.id === item.id) + 1;
                    return (
                      <button
                        key={item.id}
                        type="button"
                        onClick={() => onSelectItem(item.id)}
                        className={`w-full rounded-xl px-2.5 py-2.5 text-left transition-colors ${
                          active
                            ? 'bg-indigo-50 ring-1 ring-indigo-200'
                            : 'hover:bg-slate-50'
                        }`}
                      >
                        <div className="flex items-start gap-2">
                          <span className="mt-0.5 flex h-5 w-5 shrink-0 items-center justify-center rounded-md bg-blue-600 text-[10px] font-extrabold text-white">
                            R{idx}
                          </span>
                          <div className="min-w-0 flex-1">
                            <div className="flex flex-wrap items-center gap-1.5">
                              <span className="rounded-md bg-blue-50 px-1.5 py-0.5 text-[10px] font-extrabold text-blue-700 ring-1 ring-blue-200">
                                修订 · {revisionLabel(item.revisionKind)}
                              </span>
                              <span className="truncate text-[11px] font-medium text-slate-400">
                                {item.author}
                              </span>
                            </div>
                            {item.deletedText ? (
                              <p className="mt-1.5 text-[12px] font-medium leading-relaxed text-red-600 line-through decoration-red-400">
                                {item.deletedText}
                              </p>
                            ) : null}
                            {item.insertedText ? (
                              <p className="mt-1 text-[12px] font-semibold leading-relaxed text-blue-700 underline decoration-blue-400 decoration-2 underline-offset-2">
                                {item.insertedText}
                              </p>
                            ) : null}
                          </div>
                        </div>
                      </button>
                    );
                  }

                  const style = SEVERITY_STYLE[item.severity] || SEVERITY_STYLE['高'];
                  const globalIndex = comments.findIndex((c) => c.id === item.id) + 1 || 1;
                  return (
                    <button
                      key={item.id}
                      type="button"
                      onClick={() => onSelectItem(item.id)}
                      className={`w-full rounded-xl px-2.5 py-2.5 text-left transition-colors ${
                        active
                          ? 'bg-indigo-50 ring-1 ring-indigo-200'
                          : 'hover:bg-slate-50'
                      }`}
                    >
                      <div className="flex items-start gap-2">
                        <span
                          className={`mt-0.5 flex h-5 w-5 shrink-0 items-center justify-center rounded-md text-[10px] font-extrabold text-white ${style.dot}`}
                        >
                          {globalIndex}
                        </span>
                        <div className="min-w-0 flex-1">
                          <div className="flex flex-wrap items-center gap-1.5">
                            <span
                              className={`rounded-md px-1.5 py-0.5 text-[10px] font-extrabold ring-1 ${style.badge}`}
                            >
                              批注 · {item.severity}
                            </span>
                            <span className="truncate text-[11px] font-medium text-slate-400">
                              {item.author}
                            </span>
                          </div>
                          {item.quote ? (
                            <div className="mt-1 truncate text-[11px] font-medium text-slate-400">
                              「{item.quote}
                              {item.quote.length >= 72 ? '…' : ''}」
                            </div>
                          ) : null}
                          <p className="mt-1 line-clamp-3 text-[12px] font-medium leading-relaxed text-slate-700">
                            {item.body}
                          </p>
                        </div>
                      </div>
                    </button>
                  );
                })}
              </div>
            )}
          </div>
        </div>
      ) : null}

      <button
        type="button"
        onClick={onToggle}
        className={`pointer-events-auto inline-flex items-center gap-2 rounded-full border px-3.5 py-2 text-[12px] font-extrabold shadow-lg transition-all ${
          open
            ? 'border-indigo-200 bg-indigo-600 text-white shadow-indigo-200'
            : 'border-slate-200 bg-white text-slate-700 shadow-slate-300/40 hover:border-indigo-200 hover:text-indigo-700'
        }`}
      >
        <MessageSquareText size={14} strokeWidth={2.5} />
        审查结果
        {totalCount > 0 ? (
          <span
            className={`rounded-md px-1.5 py-0.5 text-[10px] font-extrabold tabular-nums ${
              open ? 'bg-white/20 text-white' : 'bg-slate-100 text-slate-500'
            }`}
          >
            {totalCount}
          </span>
        ) : null}
      </button>
    </div>
  );
}

function FilterChip({
  label,
  count,
  active,
  onClick,
}: {
  label: string;
  count: number;
  active: boolean;
  onClick: () => void;
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      className={`shrink-0 rounded-lg px-2 py-1 text-[11px] font-bold transition-colors ${
        active
          ? 'bg-indigo-600 text-white'
          : 'bg-slate-50 text-slate-500 hover:bg-slate-100'
      }`}
    >
      {label} {count}
    </button>
  );
}
