import React, { useEffect, useMemo, useRef, useState } from 'react';
import { ChevronDown, ChevronRight, X } from 'lucide-react';
import type { ReferenceSourceItem } from './mockSearchResult';
import { FABAO_FILTER_OPTIONS } from './mockSearchResult';
import {
  buildAdvancedFilterOptionPools,
  defaultSourceListFilters,
  CASE_COURT_LEVEL_OPTIONS,
  CASE_JUDGMENT_TIME_OPTIONS,
  CASE_REFERENCE_LEVEL_OPTIONS,
  CASE_TRIAL_PROCEDURE_OPTIONS,
  getVisibleAdvancedFilterGroups,
  hasDrillDownRegularFilters,
  type AdvancedFilterGroupKey,
  LAW_EFFECT_STATUS_OPTIONS,
  LAW_HIERARCHY_OPTIONS,
  MATCH_MODE_OPTIONS,
  MATCH_RESULT_STATUS_OPTIONS,
  MATERIAL_TYPE_OPTIONS,
  RESULT_STATUS_OPTIONS,
  SOURCE_SCOPE_OPTIONS,
  syncAdvancedFiltersWithRegularFilters,
  syncMaterialTypesWithCaseFilters,
  syncMaterialTypesWithLawFilters,
  WEB_TIME_OPTIONS,
  type CaseCourtLevelKey,
  type CaseJudgmentTimeRange,
  type CaseReferenceLevelKey,
  type CaseTrialProcedureKey,
  type LawEffectStatusFilter,
  type LawHierarchyKey,
  type MaterialTypeKey,
  type MatchModeFilter,
  type ResultStatusFilter,
  type SourceListFilters,
  type SourceScopeKey,
  type WebTimeRange,
} from './referenceSourceFilters';

export type { SourceListFilters } from './referenceSourceFilters';
export {
  defaultSourceListFilters,
  filterReferenceSources,
  getActiveFilterChips,
  isDefaultSourceListFilters,
  removeFilterChip,
  sortReferenceSources,
  syncAdvancedFiltersWithRegularFilters,
} from './referenceSourceFilters';

/** 筛选抽屉固定宽度，不随右侧来源栏拖拽宽度变化 */
export const REF_SOURCE_FILTER_DRAWER_WIDTH_PX = 360;

function pillClass(active: boolean) {
  return [
    'rounded-xl px-3 py-2 text-[12px] font-extrabold transition border',
    active
      ? 'border-blue-200 bg-blue-50 text-blue-800 ring-1 ring-blue-100/80 shadow-sm'
      : 'border-slate-200/90 bg-white text-slate-600 hover:border-slate-300 hover:bg-slate-50',
  ].join(' ');
}

const FILTER_GROUP_LABEL_CLASS = 'mb-1.5 text-[11px] font-bold text-slate-600';

function scopeToAdvancedGroup(key: SourceScopeKey): AdvancedFilterGroupKey | null {
  if (key === 'web') return 'web';
  if (key === 'pkulaw') return 'fabao';
  if (key === 'knowledge') return 'kb';
  return null;
}

function materialToAdvancedGroup(key: MaterialTypeKey): AdvancedFilterGroupKey | null {
  if (key === 'law') return 'law';
  if (key === 'case' || key === 'judgment') return 'case';
  return null;
}

const AdvancedFilterGroupSection: React.FC<{
  title: string;
  children: React.ReactNode;
}> = ({ title, children }) => (
  <div className="rounded-lg border border-slate-100 bg-white/80 p-2.5">
    <p className="mb-2 text-[11px] font-extrabold text-slate-700">{title}</p>
    {children}
  </div>
);

type ReferenceSourcesFilterModalProps = {
  open: boolean;
  onClose: () => void;
  draft: SourceListFilters;
  setDraft: React.Dispatch<React.SetStateAction<SourceListFilters>>;
  onConfirm: () => void;
  /** 当前轮次来源快照，用于动态生成高级筛选项 */
  sourceSnapshot: ReferenceSourceItem[];
  /** 参考来源 / 匹配结果，决定结果状态筛选项 */
  filterMode?: 'reference' | 'match';
};

const ReferenceSourcesFilterModal: React.FC<ReferenceSourcesFilterModalProps> = ({
  open,
  onClose,
  draft,
  setDraft,
  onConfirm,
  sourceSnapshot,
  filterMode = 'reference',
}) => {
  const [slideIn, setSlideIn] = useState(false);
  const [advancedExpanded, setAdvancedExpanded] = useState(false);
  const [scrollToGroup, setScrollToGroup] = useState<AdvancedFilterGroupKey | null>(null);
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const groupSectionRefs = useRef<Partial<Record<AdvancedFilterGroupKey, HTMLDivElement | null>>>(
    {}
  );

  const optionPools = useMemo(
    () => buildAdvancedFilterOptionPools(sourceSnapshot),
    [sourceSnapshot]
  );
  const visibleGroups = useMemo(() => getVisibleAdvancedFilterGroups(draft), [draft]);
  const showAdvancedEmptyState = advancedExpanded && !hasDrillDownRegularFilters(draft);
  const resultStatusOptions =
    filterMode === 'match' ? MATCH_RESULT_STATUS_OPTIONS : RESULT_STATUS_OPTIONS;

  useEffect(() => {
    if (!open) return;
    setAdvancedExpanded(false);
    setScrollToGroup(null);
  }, [open]);

  useEffect(() => {
    if (!scrollToGroup || !advancedExpanded || !visibleGroups.includes(scrollToGroup)) return;

    let raf2 = 0;
    const raf1 = requestAnimationFrame(() => {
      raf2 = requestAnimationFrame(() => {
        const container = scrollContainerRef.current;
        const target = groupSectionRefs.current[scrollToGroup];
        if (!container || !target) {
          setScrollToGroup(null);
          return;
        }

        const containerRect = container.getBoundingClientRect();
        const targetRect = target.getBoundingClientRect();
        const padding = 12;
        let nextScrollTop = container.scrollTop;

        if (targetRect.top < containerRect.top + padding) {
          nextScrollTop += targetRect.top - containerRect.top - padding;
        } else if (targetRect.bottom > containerRect.bottom - padding) {
          nextScrollTop += targetRect.bottom - containerRect.bottom + padding;
        }

        if (nextScrollTop !== container.scrollTop) {
          const prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
          container.scrollTo({
            top: nextScrollTop,
            behavior: prefersReducedMotion ? 'auto' : 'smooth',
          });
        }

        setScrollToGroup(null);
      });
    });

    return () => {
      cancelAnimationFrame(raf1);
      if (raf2) cancelAnimationFrame(raf2);
    };
  }, [scrollToGroup, advancedExpanded, visibleGroups]);

  useEffect(() => {
    if (!open) {
      setSlideIn(false);
      return;
    }
    const frame = requestAnimationFrame(() => setSlideIn(true));
    return () => cancelAnimationFrame(frame);
  }, [open]);

  useEffect(() => {
    if (!open) return;
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
    };
    document.addEventListener('keydown', onKeyDown);
    return () => document.removeEventListener('keydown', onKeyDown);
  }, [open, onClose]);

  if (!open) return null;

  const resetDraft = () => setDraft(defaultSourceListFilters());

  const expandAdvancedIfCollapsed = () => {
    setAdvancedExpanded((expanded) => expanded || true);
  };

  const requestScrollToGroup = (group: AdvancedFilterGroupKey) => {
    setAdvancedExpanded(true);
    setScrollToGroup(group);
  };

  const toggleScope = (key: SourceScopeKey) => {
    const willAdd = !draft.sourceScopes.includes(key);
    const group = scopeToAdvancedGroup(key);
    if (willAdd && group) {
      requestScrollToGroup(group);
    } else {
      expandAdvancedIfCollapsed();
    }
    setDraft((d) => {
      const updated: SourceListFilters = {
        ...d,
        sourceScopes: d.sourceScopes.includes(key)
          ? d.sourceScopes.filter((s) => s !== key)
          : [...d.sourceScopes, key],
      };
      return syncAdvancedFiltersWithRegularFilters(updated);
    });
  };

  const toggleMaterial = (key: MaterialTypeKey) => {
    const willAdd = !draft.materialTypes.includes(key);
    const group = materialToAdvancedGroup(key);
    if (willAdd && group) {
      requestScrollToGroup(group);
    } else {
      expandAdvancedIfCollapsed();
    }
    setDraft((d) => {
      const updated: SourceListFilters = {
        ...d,
        materialTypes: d.materialTypes.includes(key)
          ? d.materialTypes.filter((s) => s !== key)
          : [...d.materialTypes, key],
      };
      return syncAdvancedFiltersWithRegularFilters(updated);
    });
  };

  const toggleFabaoDb = (key: string) => {
    setDraft((d) => ({
      ...d,
      fabaoSelectedKeys: d.fabaoSelectedKeys.includes(key)
        ? d.fabaoSelectedKeys.filter((k) => k !== key)
        : [...d.fabaoSelectedKeys, key],
    }));
  };

  const toggleKb = (key: string) => {
    setDraft((d) => ({
      ...d,
      kbSelectedKeys: d.kbSelectedKeys.includes(key)
        ? d.kbSelectedKeys.filter((k) => k !== key)
        : [...d.kbSelectedKeys, key],
    }));
  };

  const setWebTime = (key: WebTimeRange) => {
    setDraft((d) => ({ ...d, webTime: key }));
  };

  const toggleLawHierarchy = (key: LawHierarchyKey) => {
    setDraft((d) => {
      const next: SourceListFilters = {
        ...d,
        lawHierarchyLevels: d.lawHierarchyLevels.includes(key)
          ? d.lawHierarchyLevels.filter((k) => k !== key)
          : [...d.lawHierarchyLevels, key],
      };
      return { ...next, materialTypes: syncMaterialTypesWithLawFilters(next) };
    });
  };

  const setLawEffectStatus = (key: LawEffectStatusFilter) => {
    setDraft((d) => {
      const next: SourceListFilters = { ...d, lawEffectStatus: key };
      return { ...next, materialTypes: syncMaterialTypesWithLawFilters(next) };
    });
  };

  const applyCaseFilterUpdate = (updater: (d: SourceListFilters) => SourceListFilters) => {
    setDraft((d) => {
      const next = updater(d);
      return { ...next, materialTypes: syncMaterialTypesWithCaseFilters(next) };
    });
  };

  const toggleCaseReferenceLevel = (key: CaseReferenceLevelKey) => {
    applyCaseFilterUpdate((d) => ({
      ...d,
      caseReferenceLevels: d.caseReferenceLevels.includes(key)
        ? d.caseReferenceLevels.filter((k) => k !== key)
        : [...d.caseReferenceLevels, key],
    }));
  };

  const toggleCaseCourtLevel = (key: CaseCourtLevelKey) => {
    applyCaseFilterUpdate((d) => ({
      ...d,
      caseCourtLevels: d.caseCourtLevels.includes(key)
        ? d.caseCourtLevels.filter((k) => k !== key)
        : [...d.caseCourtLevels, key],
    }));
  };

  const toggleCaseTrialProcedure = (key: CaseTrialProcedureKey) => {
    applyCaseFilterUpdate((d) => ({
      ...d,
      caseTrialProcedures: d.caseTrialProcedures.includes(key)
        ? d.caseTrialProcedures.filter((k) => k !== key)
        : [...d.caseTrialProcedures, key],
    }));
  };

  const setCaseJudgmentTime = (key: CaseJudgmentTimeRange) => {
    applyCaseFilterUpdate((d) => ({ ...d, caseJudgmentTime: key }));
  };

  const resolveKbLabel = (key: string) => {
    const fromSnapshot = sourceSnapshot.find(
      (item) => item.sourceScope === 'knowledge' && item.kbKey === key
    );
    return (
      fromSnapshot?.knowledgeBaseName ??
      fromSnapshot?.sourceLibraryName ??
      key
    );
  };

  const fabaoOptions = optionPools.fabaoDbKeys
    .map((key) => ({
      key,
      label: FABAO_FILTER_OPTIONS.find((o) => o.key === key)?.label ?? key,
    }))
    .sort((a, b) => a.label.localeCompare(b.label, 'zh-CN'));

  const kbOptions = optionPools.kbKeys
    .map((key) => ({ key, label: resolveKbLabel(key) }))
    .sort((a, b) => a.label.localeCompare(b.label, 'zh-CN'));

  const lawEffectOptions = LAW_EFFECT_STATUS_OPTIONS.filter((o) =>
    optionPools.lawEffectStatuses.includes(o.key)
  );
  const lawHierarchyOptions = LAW_HIERARCHY_OPTIONS.filter((o) =>
    optionPools.lawHierarchyLevels.includes(o.key)
  );
  const caseReferenceOptions = CASE_REFERENCE_LEVEL_OPTIONS.filter((o) =>
    optionPools.caseReferenceLevels.includes(o.key)
  );
  const caseCourtOptions = CASE_COURT_LEVEL_OPTIONS.filter((o) =>
    optionPools.caseCourtLevels.includes(o.key)
  );
  const caseTrialOptions = CASE_TRIAL_PROCEDURE_OPTIONS.filter((o) =>
    optionPools.caseTrialProcedures.includes(o.key)
  );
  const caseTimeOptions = CASE_JUDGMENT_TIME_OPTIONS.filter((o) =>
    optionPools.caseJudgmentTimeRanges.includes(o.key)
  );
  const webTimeOptions = WEB_TIME_OPTIONS.filter((o) => optionPools.webTimeRanges.includes(o.id));

  return (
    <div className="pointer-events-none absolute inset-0 z-30">
      <button
        type="button"
        className="pointer-events-auto absolute inset-0 bg-slate-900/20 transition-opacity"
        aria-label="关闭筛选"
        onClick={onClose}
      />
      <div
        role="dialog"
        aria-modal="true"
        aria-labelledby="ref-source-filter-title"
        style={{ width: REF_SOURCE_FILTER_DRAWER_WIDTH_PX }}
        className={`pointer-events-auto absolute top-0 right-0 z-40 flex h-full max-w-[calc(100%-12px)] flex-col overflow-hidden border-l border-slate-200 bg-white shadow-[-10px_0_32px_rgba(15,23,42,0.12)] transition-transform duration-300 ease-out ${
          slideIn ? 'translate-x-0' : 'translate-x-full'
        }`}
      >
        <div className="flex items-center justify-between border-b border-slate-100 px-3 py-2.5">
          <h2 id="ref-source-filter-title" className="text-[14px] font-extrabold text-slate-900">
            筛选参考来源
          </h2>
          <button
            type="button"
            onClick={onClose}
            className="rounded-lg p-1.5 text-slate-500 transition hover:bg-slate-100 hover:text-slate-800"
            aria-label="关闭"
          >
            <X size={18} strokeWidth={2.25} />
          </button>
        </div>

        <div
          ref={scrollContainerRef}
          className="custom-scrollbar flex-1 space-y-3 overflow-y-auto px-3 py-3"
        >
          <section className="rounded-xl border border-slate-100 bg-slate-50/90 p-3">
            <h3 className="mb-2.5 text-[11px] font-extrabold uppercase tracking-wide text-slate-500">
              常规筛选
            </h3>

            <p className={FILTER_GROUP_LABEL_CLASS}>结果状态</p>
            <div className="mb-3 flex flex-wrap gap-1.5">
              {resultStatusOptions.map(({ key, label }) => (
                <button
                  key={key}
                  type="button"
                  onClick={() => setDraft((d) => ({ ...d, resultStatus: key as ResultStatusFilter }))}
                  className={pillClass(draft.resultStatus === key)}
                >
                  {label}
                </button>
              ))}
            </div>

            <p className={FILTER_GROUP_LABEL_CLASS}>匹配方式</p>
            <div className="mb-3 flex flex-wrap gap-1.5">
              {MATCH_MODE_OPTIONS.map(({ key, label }) => (
                <button
                  key={key}
                  type="button"
                  onClick={() => setDraft((d) => ({ ...d, matchMode: key as MatchModeFilter }))}
                  className={pillClass(draft.matchMode === key)}
                >
                  {label}
                </button>
              ))}
            </div>

            <p className={FILTER_GROUP_LABEL_CLASS}>
              来源范围（可多选，未选表示不过滤）
            </p>
            <div className="mb-3 flex flex-wrap gap-1.5">
              {SOURCE_SCOPE_OPTIONS.map(({ key, label }) => (
                <button
                  key={key}
                  type="button"
                  onClick={() => toggleScope(key)}
                  className={pillClass(draft.sourceScopes.includes(key))}
                >
                  {label}
                </button>
              ))}
            </div>

            <p className={FILTER_GROUP_LABEL_CLASS}>
              资料类型（可多选，未选表示不过滤）
            </p>
            <div className="flex flex-wrap gap-1.5">
              {MATERIAL_TYPE_OPTIONS.map(({ key, label }) => (
                <button
                  key={key}
                  type="button"
                  onClick={() => toggleMaterial(key)}
                  className={pillClass(draft.materialTypes.includes(key))}
                >
                  {label}
                </button>
              ))}
            </div>
          </section>

          <section className="rounded-xl border border-slate-100 bg-slate-50/90 p-3">
            <button
              type="button"
              onClick={() => setAdvancedExpanded((v) => !v)}
              aria-expanded={advancedExpanded}
              className="flex w-full items-center gap-2 text-left transition hover:text-slate-900"
            >
              {advancedExpanded ? (
                <ChevronDown className="h-4 w-4 shrink-0 text-slate-400" aria-hidden />
              ) : (
                <ChevronRight className="h-4 w-4 shrink-0 text-slate-400" aria-hidden />
              )}
              <h3 className="text-[11px] font-extrabold uppercase tracking-wide text-slate-500">
                高级筛选
              </h3>
            </button>

            {showAdvancedEmptyState ? (
              <p className="mt-2 text-[12px] font-medium leading-relaxed text-slate-500">
                请先选择来源范围或资料类型，以查看可用的高级筛选项
              </p>
            ) : null}

            {advancedExpanded && visibleGroups.length > 0 ? (
              <div className="mt-2 space-y-2.5">
                {visibleGroups.includes('web') ? (
                  <div
                    ref={(el) => {
                      groupSectionRefs.current.web = el;
                    }}
                    className="scroll-mt-3"
                  >
                  <AdvancedFilterGroupSection title="全网筛选">
                    <p className={FILTER_GROUP_LABEL_CLASS}>时间范围</p>
                    <div className="flex flex-wrap gap-1.5">
                      {webTimeOptions.map(({ id, label }) => (
                        <button
                          key={id}
                          type="button"
                          onClick={() => setWebTime(id)}
                          className={pillClass(draft.webTime === id)}
                        >
                          {label}
                        </button>
                      ))}
                    </div>
                  </AdvancedFilterGroupSection>
                  </div>
                ) : null}

                {visibleGroups.includes('fabao') && fabaoOptions.length > 0 ? (
                  <div
                    ref={(el) => {
                      groupSectionRefs.current.fabao = el;
                    }}
                    className="scroll-mt-3"
                  >
                  <AdvancedFilterGroupSection title="法宝数据库筛选">
                    <div className="flex flex-wrap gap-1.5">
                      {fabaoOptions.map(({ key, label }) => (
                        <button
                          key={key}
                          type="button"
                          onClick={() => toggleFabaoDb(key)}
                          className={pillClass(draft.fabaoSelectedKeys.includes(key))}
                        >
                          {label}
                        </button>
                      ))}
                    </div>
                  </AdvancedFilterGroupSection>
                  </div>
                ) : null}

                {visibleGroups.includes('kb') && kbOptions.length > 0 ? (
                  <div
                    ref={(el) => {
                      groupSectionRefs.current.kb = el;
                    }}
                    className="scroll-mt-3"
                  >
                  <AdvancedFilterGroupSection title="知识库筛选">
                    <div className="flex flex-wrap gap-1.5">
                      {kbOptions.map(({ key, label }) => (
                        <button
                          key={key}
                          type="button"
                          onClick={() => toggleKb(key)}
                          className={pillClass(draft.kbSelectedKeys.includes(key))}
                        >
                          {label}
                        </button>
                      ))}
                    </div>
                  </AdvancedFilterGroupSection>
                  </div>
                ) : null}

                {visibleGroups.includes('law') &&
                (lawEffectOptions.length > 0 || lawHierarchyOptions.length > 0) ? (
                  <div
                    ref={(el) => {
                      groupSectionRefs.current.law = el;
                    }}
                    className="scroll-mt-3"
                  >
                  <AdvancedFilterGroupSection title="法规筛选">
                    {lawEffectOptions.length > 0 ? (
                      <div className="mb-3">
                        <p className={FILTER_GROUP_LABEL_CLASS}>效力状态</p>
                        <div className="flex flex-wrap gap-1.5">
                          {lawEffectOptions.map(({ key, label }) => (
                            <button
                              key={key}
                              type="button"
                              onClick={() => setLawEffectStatus(key as LawEffectStatusFilter)}
                              className={pillClass(draft.lawEffectStatus === key)}
                            >
                              {label}
                            </button>
                          ))}
                        </div>
                      </div>
                    ) : null}

                    {lawHierarchyOptions.length > 0 ? (
                      <div>
                        <p className={FILTER_GROUP_LABEL_CLASS}>法规位阶</p>
                        <div className="flex flex-wrap gap-1.5">
                          {lawHierarchyOptions.map(({ key, label }) => (
                            <button
                              key={key}
                              type="button"
                              onClick={() => toggleLawHierarchy(key)}
                              className={pillClass(draft.lawHierarchyLevels.includes(key))}
                            >
                              {label}
                            </button>
                          ))}
                        </div>
                      </div>
                    ) : null}
                  </AdvancedFilterGroupSection>
                  </div>
                ) : null}

                {visibleGroups.includes('case') &&
                (caseReferenceOptions.length > 0 ||
                  caseCourtOptions.length > 0 ||
                  caseTrialOptions.length > 0 ||
                  caseTimeOptions.length > 0) ? (
                  <div
                    ref={(el) => {
                      groupSectionRefs.current.case = el;
                    }}
                    className="scroll-mt-3"
                  >
                  <AdvancedFilterGroupSection title="案例筛选">
                    {caseReferenceOptions.length > 0 ? (
                      <div className="mb-3">
                        <p className={FILTER_GROUP_LABEL_CLASS}>案例类型</p>
                        <div className="flex flex-wrap gap-1.5">
                          {caseReferenceOptions.map(({ key, label }) => (
                            <button
                              key={key}
                              type="button"
                              onClick={() => toggleCaseReferenceLevel(key)}
                              className={pillClass(draft.caseReferenceLevels.includes(key))}
                            >
                              {label}
                            </button>
                          ))}
                        </div>
                      </div>
                    ) : null}

                    {caseCourtOptions.length > 0 ? (
                      <div className="mb-3">
                        <p className={FILTER_GROUP_LABEL_CLASS}>法院层级</p>
                        <div className="flex flex-wrap gap-1.5">
                          {caseCourtOptions.map(({ key, label }) => (
                            <button
                              key={key}
                              type="button"
                              onClick={() => toggleCaseCourtLevel(key)}
                              className={pillClass(draft.caseCourtLevels.includes(key))}
                            >
                              {label}
                            </button>
                          ))}
                        </div>
                      </div>
                    ) : null}

                    {caseTrialOptions.length > 0 ? (
                      <div className="mb-3">
                        <p className={FILTER_GROUP_LABEL_CLASS}>审级/程序</p>
                        <div className="flex flex-wrap gap-1.5">
                          {caseTrialOptions.map(({ key, label }) => (
                            <button
                              key={key}
                              type="button"
                              onClick={() => toggleCaseTrialProcedure(key)}
                              className={pillClass(draft.caseTrialProcedures.includes(key))}
                            >
                              {label}
                            </button>
                          ))}
                        </div>
                      </div>
                    ) : null}

                    {caseTimeOptions.length > 0 ? (
                      <div>
                        <p className={FILTER_GROUP_LABEL_CLASS}>裁判时间</p>
                        <div className="flex flex-wrap gap-1.5">
                          {caseTimeOptions.map(({ key, label }) => (
                            <button
                              key={key}
                              type="button"
                              onClick={() => setCaseJudgmentTime(key)}
                              className={pillClass(draft.caseJudgmentTime === key)}
                            >
                              {label}
                            </button>
                          ))}
                        </div>
                      </div>
                    ) : null}
                  </AdvancedFilterGroupSection>
                  </div>
                ) : null}
              </div>
            ) : null}
          </section>
        </div>

        <div className="flex justify-end gap-2 border-t border-slate-100 px-3 py-2.5">
          <button
            type="button"
            onClick={resetDraft}
            className="rounded-xl border border-slate-200 bg-white px-3.5 py-1.5 text-[12px] font-extrabold text-slate-700 transition hover:bg-slate-50"
          >
            重置
          </button>
          <button
            type="button"
            onClick={onConfirm}
            className="rounded-xl bg-blue-600 px-4 py-1.5 text-[12px] font-extrabold text-white shadow-sm transition hover:bg-blue-700"
          >
            确认筛选
          </button>
        </div>
      </div>
    </div>
  );
};

export default ReferenceSourcesFilterModal;
