/**
 * PDF 操作工具包：模拟「生成 PDF」后的短引导语 + 文档卡片元数据（标题、生成时间）。
 */
export function buildMockPdfSkillDocument(userQuestion) {
  const raw =
    typeof userQuestion === 'string' && userQuestion.trim()
      ? userQuestion.trim()
      : '未命名文档';
  const base =
    raw.length > 28 ? `${raw.slice(0, 28)}…` : raw;
  const title = /\.pdf$/i.test(base) ? base : `${base}.pdf`;
  const now = new Date();
  const generatedAt = now.toLocaleString('zh-CN', {
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false,
  });
  const intro = `已根据您的指令生成 PDF 文档。您可在下方文档卡片中查看文件名与生成时间，也可点击卡片在编辑器中打开预览（演示）。\n\n文档：${title}`;
  return {
    intro,
    document: { title, generatedAt },
  };
}
